 if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){if(!post_csrf()){http_response_code(403);exit('CSRF validation failed');}$a=(string)$_POST['action'];$n=(string)($_POST['file']??'');$st=state_read();
