icle class="stat"><span class="stat-icon">'.icon('<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5"/>').'</span><label>'.e($t['storage']).'</label><strong>'.e(number_format($bytes/1048576,1).' MB').'</strong></article></section>';
